package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/synth"
	"github.com/gitdek/invariant/internal/tla"
	"github.com/gitdek/invariant/internal/toolchain"
)

// Intended production seam: modeledGateTool(p, workspace, toolchain, maxRuns,
// logPath) returns the very mcp.Tool installed by mcpCmd. It extracts the current
// closure without substituting verification, project staging or log writing.
// verifyCmd already has its own preparation seam, verifyToolchain.
func init() {
	if os.Getenv("CLI946_DOCKER") != "1" {
		return
	}
	args := os.Args[1:]
	all := " " + strings.Join(args, " ") + " "
	if len(args) > 0 && args[0] == "run" && strings.Contains(all, " gobra946 ") {
		mounts := map[string]string{}
		report := ""
		for i, arg := range args[:len(args)-1] {
			if arg == "-v" || arg == "--volume" {
				parts := strings.Split(args[i+1], ":")
				if len(parts) >= 2 {
					mounts[parts[1]] = parts[0]
				}
			}
			if arg == "-g" {
				report = args[i+1]
			}
		}
		if host := mounts[report]; report != "" && host != "" {
			if err := os.WriteFile(filepath.Join(host, "stats.json"), []byte(cli946TimeoutStats), 0644); err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(91)
			}
		}
		fmt.Print(cli946TimeoutOutput)
		os.Exit(1)
	}
	if len(args) > 0 && args[0] == "run" && strings.Contains(all, " go946 ") {
		fmt.Print("@@invariant vet=0\n@@invariant test=0\ninvariant-agreement states=3 depth=3\n@@invariant agree=0\n")
		os.Exit(0)
	}
	os.Exit(reader603Docker(args))
}
func cli946Fixture(t *testing.T) (string, toolchain.Toolchain) {
	t.Helper()
	tc, _ := reader603Tools(t)
	tc.GobraImage = "gobra946"
	tc.GoImage = "go946"
	bin := t.TempDir()
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	script := "#!/bin/sh\nexport CLI946_DOCKER=1\nexec '" + strings.ReplaceAll(exe, "'", "'\"'\"'") + "' \"$@\"\n"
	path := filepath.Join(bin, "docker")
	reader603Write(t, path, script)
	if err := os.Chmod(path, 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	dir := t.TempDir()
	m := project.Manifest{Name: "timeout diagnostics", Module: ".invariant/specs/Reader603.tla", Code: "tiny", Language: "go"}
	lock := project.Lock{Decision: "timeout-fixture", Bounds: map[string]string{"Limit": "2"}, Statements: []project.Statement{{Name: "Spec", Kind: project.Spec, Says: "Advance, reset or poll."}, {Name: "Safe", Kind: project.Invariant, Says: "The count stays in bounds."}}}
	for i := range lock.Statements {
		h, err := tla.PinHashWith(reader603Model, map[string]string{"Helper603.tla": reader603Include}, lock.Statements[i].Name, project.Model)
		if err != nil {
			t.Fatal(err)
		}
		lock.Statements[i].SHA256 = h
	}
	for name, body := range map[string]string{
		".invariant/invariant.json": string(reader603JSON(t, m)), ".invariant/ratified.lock": string(reader603JSON(t, lock)),
		".invariant/request.md": "Build the tiny example.", ".invariant/specs/Reader603.tla": reader603Model, ".invariant/specs/Helper603.tla": reader603Include,
		"go.mod":          "module example/tiny\n\ngo 1.27.1\n",
		"tiny/tiny.go":    cli946TimeoutSource,
		"tiny/explore.go": "package tiny\ntype State int\nfunc Init() State {return 0}\nfunc Successors(s State) []State {return []State{(s+1)%3}}\n",
	} {
		reader603Write(t, filepath.Join(dir, name), body)
	}
	return dir, tc
}
func cli946Diagnostic(t *testing.T, text string) {
	t.Helper()
	for _, want := range []string{"Gobra", "tiny.go", "Branches", "(*Alpha).Start", "252ms", "(Beta).Start", "355ms", "Inc", "197ms", "package initialization", "6ms"} {
		if !strings.Contains(text, want) {
			t.Errorf("missing %q:\n%s", want, text)
		}
	}
	if !strings.Contains(strings.ToLower(text), "unfinished") && !strings.Contains(text, "did not terminate") {
		t.Errorf("lost unfinished status:\n%s", text)
	}
	if strings.Contains(text, "Successors") {
		t.Errorf("unselected explorer reported as pending:\n%s", text)
	}
}
func TestGobra946CIGateNamesUnfinishedProof(t *testing.T) {
	dir, tc := cli946Fixture(t)
	old := verifyToolchain
	verifyToolchain = func(context.Context) (toolchain.Toolchain, error) { return tc, nil }
	t.Cleanup(func() { verifyToolchain = old })
	stdout, err := os.CreateTemp(t.TempDir(), "stdout")
	if err != nil {
		t.Fatal(err)
	}
	defer stdout.Close()
	stderr, err := os.CreateTemp(t.TempDir(), "stderr")
	if err != nil {
		t.Fatal(err)
	}
	defer stderr.Close()
	oldOut, oldErr := os.Stdout, os.Stderr
	os.Stdout, os.Stderr = stdout, stderr
	defer func() { os.Stdout, os.Stderr = oldOut, oldErr }()
	outDir := filepath.Join(t.TempDir(), "gate")
	code := verifyCmd(t.Context(), []string{"-out", outDir, dir})
	os.Stdout, os.Stderr = oldOut, oldErr
	if code != 2 {
		t.Errorf("timeout must remain a gate error (2), got %d", code)
	}
	text, err := os.ReadFile(stderr.Name())
	if err != nil {
		t.Fatal(err)
	}
	cli946Diagnostic(t, string(text))
	if strings.Contains(string(text), dir) {
		t.Fatal("gate diagnostic exposed host source path")
	}
	if _, err := os.Stat(filepath.Join(outDir, "receipt.json")); !os.IsNotExist(err) {
		t.Fatalf("timeout acquired a failed-Code receipt: %v", err)
	}
}
func TestGobra946AgentGateNamesUnfinishedProof(t *testing.T) {
	dir, tc := cli946Fixture(t)
	p, err := project.Load(dir)
	if err != nil {
		t.Fatal(err)
	}
	log := filepath.Join(t.TempDir(), "gate.jsonl")
	tool := modeledGateTool(p, dir, tc, 4, log)
	if tool.Name != "gate" {
		t.Fatalf("wrong modeled tool: %s", tool.Name)
	}
	text, isError := tool.Call(t.Context(), json.RawMessage(`{}`))
	if !isError || !strings.Contains(text, "The gate couldn't run") {
		t.Fatalf("timeout changed tool outcome: %t %s", isError, text)
	}
	cli946Diagnostic(t, text)
	if !strings.Contains(text, "Gate run 1 of 4") {
		t.Fatal("timeout stopped consuming the run allowance")
	}
	b, err := os.ReadFile(log)
	if err != nil {
		t.Fatal(err)
	}
	var run synth.GateRun
	if err := json.Unmarshal(b, &run); err != nil {
		t.Fatal(err)
	}
	if run.Passed || run.Run != 1 {
		t.Fatalf("wrong timeout run record: %+v", run)
	}
	cli946Diagnostic(t, strings.Join(run.Failed, "\n"))
}

