// Intended API: ParseRun(dir, combinedOutput, statsJSON, exitCode) (Result, error)
// is the same interpretation Run uses. Result.Members contains diagnostic
// Member values with ID, File, Symbol, Reported, HasBody, Verified, Success and Duration.
// Symbols use Go receiver notation: (*Alpha).Start and (Beta).Start.
// A Package member uses Symbol "package initialization" and no invented File.
// HasBody means at least one Viper member has hasBody=true; only these Viper
// members contribute to Verified and Duration. Rows without bodies are neither
// completed nor unfinished. Explicit "did not terminate" messages still survive.
// Duration is time.Duration; it is meaningful only for Verified members.
// PackageTimeout defaults to 19m30s, independently of the 20m Timeout backstop.
// No field asserts that a member is currently active.
//
// Both captures below are supplied verbatim in the issue, including package
// initialization. The builder needs no Docker or network to replay them.
// The integration regression uses the supplied Branches source at 2 CPUs,
// a 40-second package limit and a 2-minute backstop, through the pinned tool;
// it fails rather than skips missing prerequisites when run with integration.
// The capture assertions deliberately read the raw JSON independently:
// neither an AST inventory nor a preconstructed progress value can feed them.

type raw946 struct {
	nodeType          string
	hasBody           bool
	verified, success bool
	duration          time.Duration
}

func write946(t *testing.T, path, body string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(body), 0644); err != nil {
		t.Fatal(err)
	}
}
func read946(t *testing.T, path string) []byte {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return b
}
func capture946(t *testing.T, kind string) (string, string, []byte, int) {
	t.Helper()
	dir := t.TempDir()
	source, out, stats, code := capture946FinishedSource, capture946FinishedOutput, capture946FinishedStats, 0
	if kind == "timeout" {
		source, out, stats, code = capture946TimeoutSource, capture946TimeoutOutput, capture946TimeoutStats, 1
	} else if kind == "failed" {
		// Derived failure case, not a claimed third real capture.
		out = strings.Replace(out, "Gobra found 0 errors", "Gobra found 1 errors", 1)
		stats = strings.Replace(stats, `"success": true`, `"success": false`, 1)
		code = 1
	} else if kind != "finished" {
		t.Fatalf("unknown capture: %s", kind)
	}
	write946(t, filepath.Join(dir, "tiny.go"), source)
	return dir, out, []byte(stats), code
}

// Read the pinned image's actual array and viperMembers schema independently.
// A bodiless leaf's time may be nonzero even though it is never verified.
func rawMembers946(t *testing.T, stats []byte) map[string]raw946 {
	t.Helper()
	var root []struct {
		ID, NodeType string
		ViperMembers []struct {
			HasBody, Verified, Success bool
			Time                       float64
		}
	}
	if err := json.Unmarshal(stats, &root); err != nil {
		t.Fatal(err)
	}
	result := map[string]raw946{}
	for _, member := range root {
		if _, duplicate := result[member.ID]; duplicate {
			t.Fatalf("duplicate member %s", member.ID)
		}
		r := raw946{nodeType: member.NodeType, verified: true, success: true}
		for _, leaf := range member.ViperMembers {
			if !leaf.HasBody {
				continue
			}
			r.hasBody = true
			r.verified = r.verified && leaf.Verified
			r.success = r.success && leaf.Success
			r.duration += time.Duration(leaf.Time * float64(time.Millisecond))
		}
		r.verified = r.hasBody && r.verified
		result[member.ID] = r
	}
	if len(result) < 2 {
		t.Fatalf("capture has no usable Go member statistics: %s", stats)
	}
	return result
}
func symbols946(t *testing.T, dir string) map[string]string {
	t.Helper()
	f, err := parser.ParseFile(token.NewFileSet(), filepath.Join(dir, "tiny.go"), nil, 0)
	if err != nil {
		t.Fatal(err)
	}
	symbols := map[string]string{}
	for _, d := range f.Decls {
		fn, ok := d.(*ast.FuncDecl)
		if !ok {
			continue
		}
		key, symbol := fn.Name.Name, fn.Name.Name
		if fn.Recv != nil {
			r := fn.Recv.List[0].Type
			prefix := ""
			if star, ok := r.(*ast.StarExpr); ok {
				prefix = "*"
				r = star.X
			}
			name, ok := r.(*ast.Ident)
			if !ok {
				t.Fatalf("capture needs a simple named receiver: %T", r)
			}
			key = prefix + name.Name + "." + fn.Name.Name
			symbol = "(" + prefix + name.Name + ")." + fn.Name.Name
		}
		symbols[key] = symbol
	}
	return symbols
}
func checkCapture946(t *testing.T, dir string, stats []byte, got gobra.Result) (int, int) {
	t.Helper()
	raw := rawMembers946(t, stats)
	symbols := symbols946(t, dir)
	seen := map[string]bool{}
	complete, unfinished := 0, 0
	for _, member := range got.Members {
		expected, ok := raw[member.ID]
		if !ok {
			continue
		} // Inventory rows may additionally say not reported.
		if seen[member.ID] {
			t.Fatalf("duplicate diagnostic member %s", member.ID)
		}
		seen[member.ID] = true
		file, symbol := "", "package initialization"
		if expected.nodeType != "Package" {
			key, _, _ := strings.Cut(strings.TrimPrefix(member.ID, ".. - tiny."), "(")
			var exists bool
			symbol, exists = symbols[key]
			if !exists {
				t.Fatalf("captured member %q has no Go declaration", member.ID)
			}
			file = "tiny.go"
		}
		if member.File != file || member.Symbol != symbol || !member.Reported || member.HasBody != expected.hasBody || member.Verified != expected.verified {
			t.Fatalf("source/status differs from raw capture: %+v, expected %s %+v", member, symbol, expected)
		}
		if member.Verified {
			complete++
			if member.Duration != expected.duration || member.Success != expected.success {
				t.Fatalf("lost measured completion: %+v, raw %+v", member, expected)
			}
		} else if member.HasBody {
			unfinished++
			if member.Duration != 0 {
				t.Fatalf("fabricated completed timing: %+v", member)
			}
		}
	}
	if len(seen) != len(raw) {
		t.Fatalf("only %d of %d raw members survived: %+v", len(seen), len(raw), got.Members)
	}
	return complete, unfinished
}

func TestGobra946CapturedReports(t *testing.T) {
	for _, kind := range []string{"finished", "timeout"} {
		t.Run(kind, func(t *testing.T) {
			dir, out, stats, code := capture946(t, kind)
			got, err := gobra.ParseRun(dir, out, stats, code)
			complete, unfinished := checkCapture946(t, dir, stats, got)
			if kind == "finished" {
				if err != nil || complete != 4 || unfinished != 0 {
					t.Fatalf("finished capture: %+v %v", got, err)
				}
				names := map[string]bool{}
				for _, m := range got.Members {
					names[m.Symbol] = true
				}
				if !names["(*Alpha).Start"] || !names["(Beta).Start"] {
					t.Fatal("finished capture must distinguish two receivers with the same method name")
				}
				if got.Passed != (code == 0) {
					t.Fatal("diagnostics changed the verification outcome")
				}
				// Alter an actual captured leaf, rather than hand-building progress.
				var data any
				_ = json.Unmarshal(stats, &data)
				changed := false
				var failOne func(any)
				failOne = func(v any) {
					switch x := v.(type) {
					case []any:
						for _, e := range x {
							failOne(e)
						}
					case map[string]any:
						if !changed && x["verified"] == true {
							if _, ok := x["success"].(bool); ok {
								x["success"] = false
								changed = true
							}
						}
						for _, e := range x {
							failOne(e)
						}
					}
				}
				failOne(data)
				if !changed {
					t.Fatal("no completed raw leaf")
				}
				failed, _ := json.Marshal(data)
				res, e := gobra.ParseRun(dir, "Gobra found 1 errors.\n", failed, 1)
				if e != nil || res.Passed {
					t.Fatalf("ordinary failed proof became a gate error or pass: %+v %v", res, e)
				}
				checkCapture946(t, dir, failed, res)
			} else {
				if err == nil || got.Passed || complete != 4 || unfinished != 1 || !strings.Contains(out, "did not terminate") {
					t.Fatalf("need a genuine mixed timeout capture: %+v %v", got, err)
				}
				for _, m := range got.Members {
					if !m.Reported {
						continue
					}
					if !strings.Contains(err.Error(), m.Symbol) || !strings.Contains(err.Error(), m.File) {
						t.Fatalf("timeout omitted member: %+v\n%v", m, err)
					}
					if m.Verified && !strings.Contains(err.Error(), m.Duration.String()) {
						t.Fatalf("timeout omitted measured duration: %+v\n%v", m, err)
					}
				}
			}
		})
	}
}

func TestGobra946BodylessReportsAreNotPending(t *testing.T) {
	for _, kind := range []string{"finished", "timeout"} {
		t.Run(kind, func(t *testing.T) {
			dir, out, stats, code := capture946(t, kind)
			src := string(read946(t, filepath.Join(dir, "tiny.go")))
			write946(t, filepath.Join(dir, "tiny.go"), src+"\n// @ pure\nfunc Pure(x int) (r int)\n")
			// Synthetic regression derived from the captures and the reported
			// abstract-member shape. It is not presented as another tool capture.
			var data []map[string]any
			if err := json.Unmarshal(stats, &data); err != nil {
				t.Fatal(err)
			}
			bodyless := map[string]any{"name": "Pure_F", "taskName": ".. - tiny", "time": 4,
				"nodeType": "Function", "success": true, "cached": false,
				"fromImport": false, "hasBody": false, "verified": false}
			data = append(data, map[string]any{"id": ".. - tiny.Pure(int)", "pkgId": ".. - tiny", "pkg": "tiny",
				"name": "tiny.Pure", "args": "(int)", "nodeType": "FunctionDeclaration", "abstract": true,
				"trusted": false, "viperMembers": []any{bodyless}, "dependencies": []any{}})
			// An auxiliary bodiless Viper member must not block a real completed
			// body or add its 4 ms to that body's measured proof time.
			leaves := data[0]["viperMembers"].([]any)
			data[0]["viperMembers"] = append(leaves, bodyless)
			stats, err := json.Marshal(data)
			if err != nil {
				t.Fatal(err)
			}
			got, err := gobra.ParseRun(dir, out, stats, code)
			complete, unfinished := checkCapture946(t, dir, stats, got)
			wantUnfinished := 0
			if kind == "timeout" {
				wantUnfinished = 1
			}
			if complete != 4 || unfinished != wantUnfinished || (err != nil) != (kind == "timeout") || got.Passed != (kind == "finished") {
				t.Fatalf("bodiless declaration changed proof outcome/progress: %+v %v", got, err)
			}
			for _, member := range got.Members {
				if member.Symbol == "Pure" && (member.HasBody || member.Verified || member.Duration != 0) {
					t.Fatalf("bodiless declaration counted as a proof: %+v", member)
				}
			}
			if err != nil && strings.Contains(err.Error(), "Pure") {
				t.Fatalf("bodiless declaration reported as pending: %v", err)
			}
			// An explicit message is still evidence even for a bodyless entry;
			// don't discard it on an unprobed assumption about abstract/trusted code.
			_, explicit := gobra.ParseRun(dir,
				"The verification of package .. - tiny timed out after 40 seconds.\n"+
					"The verification of member .. - tiny.Pure(int) did not terminate\n"+
					"The verification of 1 member timed out.\n", stats, 1)
			if explicit == nil || !strings.Contains(explicit.Error(), "Pure") || !strings.Contains(explicit.Error(), "tiny.go") {
				t.Fatalf("explicit timeout evidence was discarded: %v", explicit)
			}
		})
	}
}

func TestGobra946PackageInitializationCanTimeOut(t *testing.T) {
	dir, _, stats, _ := capture946(t, "finished")
	var data []map[string]any
	if err := json.Unmarshal(stats, &data); err != nil {
		t.Fatal(err)
	}
	// Synthetic timeout of the real package-initialization obligation. It has
	// no source declaration, but its identity must not vanish from diagnostics.
	for _, member := range data {
		if member["nodeType"] == "Package" {
			for _, item := range member["viperMembers"].([]any) {
				leaf := item.(map[string]any)
				leaf["verified"], leaf["time"] = false, 0
			}
		}
	}
	stats, err := json.Marshal(data)
	if err != nil {
		t.Fatal(err)
	}
	out := "The verification of package .. - tiny timed out after 40 seconds.\n" +
		"The verification of member .. - tiny... - tiny_package_init did not terminate\n" +
		"The verification of 1 member timed out.\n"
	got, err := gobra.ParseRun(dir, out, stats, 1)
	complete, unfinished := checkCapture946(t, dir, stats, got)
	if err == nil || got.Passed || complete != 3 || unfinished != 1 {
		t.Fatalf("package initialization timeout lost: %+v %v", got, err)
	}
	if !strings.Contains(err.Error(), "package initialization") ||
		(!strings.Contains(strings.ToLower(err.Error()), "unfinished") && !strings.Contains(err.Error(), "did not terminate")) {
		t.Fatalf("package initialization timeout is unnamed: %v", err)
	}
}

// Replay only process output and files; never return a Result from the fake.
func init() {
	if os.Getenv("GOBRA946_DOCKER_CHILD") != "1" {
		return
	}
	args := os.Args[1:]
	if len(args) == 0 {
		os.Exit(91)
	}
	if args[0] != "run" {
		os.Exit(0)
	}
	_ = os.WriteFile(os.Getenv("GOBRA946_ARGS"), []byte(strings.Join(args, "\n")), 0600)
	mounts := map[string]string{}
	report := ""
	for i, a := range args {
		if i+1 == len(args) {
			continue
		}
		if a == "-v" || a == "--volume" {
			p := strings.Split(args[i+1], ":")
			if len(p) >= 2 {
				mounts[p[1]] = p[0]
			}
		}
		if a == "-g" {
			report = args[i+1]
		}
	}
	if src := os.Getenv("GOBRA946_STATS"); src != "" && report != "" {
		for guest, host := range mounts {
			if report == guest || strings.HasPrefix(report, guest+"/") {
				dest := filepath.Join(host, strings.TrimPrefix(report, guest))
				if err := os.MkdirAll(dest, 0755); err != nil {
					fmt.Fprintln(os.Stderr, err)
					os.Exit(92)
				}
				b, err := os.ReadFile(src)
				if err != nil {
					os.Exit(93)
				}
				if err = os.WriteFile(filepath.Join(dest, "stats.json"), b, 0644); err != nil {
					os.Exit(94)
				}
			}
		}
	}
	fmt.Print(os.Getenv("GOBRA946_OUTPUT"))
	code, _ := strconv.Atoi(os.Getenv("GOBRA946_EXIT"))
	os.Exit(code)
}
func docker946(t *testing.T, out string, stats []byte, code int) string {
	t.Helper()
	bin := t.TempDir()
	log := filepath.Join(t.TempDir(), "args")
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	script := "#!/bin/sh\nexport GOBRA946_DOCKER_CHILD=1\nexec '" + strings.ReplaceAll(exe, "'", "'\"'\"'") + "' \"$@\"\n"
	write946(t, filepath.Join(bin, "docker"), script)
	if err := os.Chmod(filepath.Join(bin, "docker"), 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("GOBRA946_OUTPUT", out)
	t.Setenv("GOBRA946_EXIT", strconv.Itoa(code))
	t.Setenv("GOBRA946_ARGS", log)
	t.Setenv("GOBRA946_STATS", "")
	if stats != nil {
		p := filepath.Join(t.TempDir(), "stats.json")
		write946(t, p, string(stats))
		t.Setenv("GOBRA946_STATS", p)
	}
	return log
}
func TestGobra946RunCollectsStatistics(t *testing.T) {
	if gobra.Timeout != 20*time.Minute || gobra.PackageTimeout != 19*time.Minute+30*time.Second {
		t.Fatal("F1 A's two limits changed")
	}
	for _, kind := range []string{"finished", "failed", "timeout"} {
		t.Run(kind, func(t *testing.T) {
			dir, out, stats, code := capture946(t, kind)
			log := docker946(t, out, stats, code)
			got, err := gobra.Run(t.Context(), "gobra946", dir, true)
			if (err != nil) != (kind == "timeout") {
				t.Fatalf("wrong timeout classification: %v", err)
			}
			if got.Passed != (kind == "finished") {
				t.Fatalf("diagnostics changed the proof outcome: %+v", got)
			}
			checkCapture946(t, dir, stats, got)
			args := strings.Split(string(read946(t, log)), "\n")
			value := func(flag string) string {
				for i, a := range args {
					if a == flag && i+1 < len(args) {
						return args[i+1]
					}
				}
				return ""
			}
			inner := value("--packageTimeout")
			if inner != "1170s" {
				t.Fatalf("package timeout = %q", inner)
			}
			if value("--network") != "none" || value("--platform") != "linux/amd64" || !strings.Contains("\n"+strings.Join(args, "\n")+"\n", "\n--overflow\n") {
				t.Fatalf("lost sandbox/overflow: %v", args)
			}
			report := value("-g")
			host := ""
			workRO := false
			for i, a := range args {
				if (a == "-v" || a == "--volume") && i+1 < len(args) {
					p := strings.Split(args[i+1], ":")
					if len(p) < 2 {
						continue
					}
					if p[1] == "/work" {
						workRO = len(p) == 3 && p[2] == "ro"
						continue
					}
					if p[1] == report {
						if len(p) == 3 && p[2] == "ro" {
							t.Fatal("read-only statistics mount")
						}
						host = p[0]
					}
				}
			}
			if !workRO || host == "" || report == "/work" || strings.HasPrefix(report, "/work/") {
				t.Fatalf("no separate writable report directory: %v", args)
			}
			if _, err := os.Stat(host); !os.IsNotExist(err) {
				t.Fatalf("report directory not cleaned: %v", err)
			}
			if _, err := os.Stat(filepath.Join(dir, "stats.json")); !os.IsNotExist(err) {
				t.Fatal("statistics written into the source tree")
			}
		})
	}
}

