func TestGobra946BothTimeoutShapes(t *testing.T) {
	for _, tc := range []struct {
		name, out string
		exit      int
	}{{"during verification", capture946TimeoutOutput, 1}, {"during desugaring", "The verification of package .. - tiny timed out after 4 seconds.\n", 0}} {
