package verify_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/gobra"
	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/verify"
)

func gate946Write(t *testing.T, path string, b []byte) {
	t.Helper()
	if e := os.WriteFile(path, b, 0644); e != nil {
		t.Fatal(e)
	}
}
func gate946Quote(s string) string { return "'" + strings.ReplaceAll(s, "'", "'\"'\"'") + "'" }

func TestGobra946FinishedGateShowsMeasuredTimes(t *testing.T) {
	dir := t.TempDir()
	gate946Write(t, filepath.Join(dir, "tiny.go"), []byte(gate946FinishedSource))
	output := []byte(gate946FinishedOutput)
	stats := []byte(gate946FinishedStats)
	expected, e := gobra.ParseRun(dir, string(output), stats, 0)
	if e != nil {
		t.Fatal(e)
	}
	bin := t.TempDir()
	statsPath := filepath.Join(bin, "statistics.json")
	outputPath := filepath.Join(bin, "output.txt")
	gate946Write(t, statsPath, stats)
	gate946Write(t, outputPath, output)
	// Docker's only substituted behavior is producing Gobra's captured bytes.
	script := `#!/bin/sh
[ "$1" = run ] || exit 0
report=''; host=''
args="$*"
while [ "$#" -gt 0 ]; do
 case "$1" in
 -v|--volume) shift; mount="$1"; guest="${mount#*:}"; guest="${guest%%:*}"; case "$guest" in /work) ;; *) host="${mount%%:*}"; output_guest="$guest";; esac ;;
 -g) shift; report="$1" ;;
 esac
 shift
done
if [ -n "$report" ] && [ "$report" = "$output_guest" ]; then
 cp ` + gate946Quote(statsPath) + ` "$host/stats.json" || exit 91
fi
cat ` + gate946Quote(outputPath) + `
exit 0
`
	docker := filepath.Join(bin, "docker")
	gate946Write(t, docker, []byte(script))
	if e := os.Chmod(docker, 0755); e != nil {
		t.Fatal(e)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	language := verify.Go{GobraImage: "gobra946"}
	got, err := language.Verify(t.Context(), dir)
	if err != nil || got == nil {
		t.Fatalf("Verify: %+v %v", got, err)
	}
	if !reflect.DeepEqual(got.Members, expected.Members) {
		t.Fatalf("Go.Verify discarded diagnostics: %+v", got)
	}
	r := verify.Report{Project: "measured", Code: got, Build: verify.Build{Passed: true}}
	members := append([]gobra.Member(nil), expected.Members...)
	sort.SliceStable(members, func(i, j int) bool { return members[i].Duration > members[j].Duration })
	complete := 0
	for label, text := range map[string]string{"agent feedback": verify.Feedback(&r), "CI receipt": receipt.Markdown(&r)} {
		last := -1
		for _, member := range members {
			if !member.Verified {
				continue
			}
			complete++
			pos := -1
			offset := 0
			for _, line := range strings.Split(text, "\n") {
				if strings.Contains(line, member.Symbol) && strings.Contains(line, member.File) && strings.Contains(line, member.Duration.String()) {
					pos = offset
					break
				}
				offset += len(line) + 1
			}
			if pos < 0 {
				t.Fatalf("%s lost measured member %+v:\n%s", label, member, text)
			}
			if pos < last {
				t.Fatalf("%s is not ordered slowest first:\n%s", label, text)
			}
			last = pos
		}
	}
	if complete != 8 {
		t.Fatal("need all three Go members and package initialization in both outputs")
	}
	before, _ := json.Marshal(r)
	fingerprint := verify.Fingerprint(r)
	after, _ := json.Marshal(r)
	if string(before) != string(after) {
		t.Fatal("fingerprinting mutated diagnostics")
	}
	// Timings are observable through the verifier, but are not proof evidence.
	var data any
	if err := json.Unmarshal(stats, &data); err != nil {
		t.Fatal(err)
	}
	var change func(any)
	change = func(v any) {
		switch x := v.(type) {
		case []any:
			for _, e := range x {
				change(e)
			}
		case map[string]any:
			if x["verified"] == true {
				if n, ok := x["time"].(float64); ok {
					x["time"] = n + 1234
				}
			}
			for _, e := range x {
				change(e)
			}
		}
	}
	change(data)
	updated, _ := json.Marshal(data)
	gate946Write(t, statsPath, updated)
	again, err := language.Verify(t.Context(), dir)
	if err != nil {
		t.Fatal(err)
	}
	if reflect.DeepEqual(again.Members, got.Members) {
		t.Fatal("changed raw millisecond values did not reach diagnostics")
	}
	r2 := r
	r2.Code = again
	if verify.Fingerprint(r2) != fingerprint {
		t.Fatal("timings changed the portable proof fingerprint")
	}
	// No synthetic zero timing may replace a missing or malformed report, and
	// diagnostics cannot turn an otherwise completed verifier run into an error.
	for _, bad := range []string{"", "{truncated"} {
		gate946Write(t, statsPath, []byte(bad))
		c, err := language.Verify(t.Context(), dir)
		if err != nil || c.Passed != got.Passed {
			t.Fatalf("missing statistics changed proof outcome: %+v %v", c, err)
		}
		for _, m := range c.Members {
			if m.Reported || m.Verified || m.Duration != 0*time.Second {
				t.Fatalf("invented completion without a report: %+v", m)
			}
		}
		text := verify.Feedback(&verify.Report{Code: c})
		if !strings.Contains(strings.ToLower(text), "not reported") {
			t.Fatalf("missing-report limitation is hidden: %s", text)
		}
	}
}

