package factory

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/synth"
	"github.com/gitdek/invariant/internal/verify"
)

func TestGobra946FactoryPostNamesUnfinishedProof(t *testing.T) {
	dir := t.TempDir()
	bin := t.TempDir()
	write := func(path, body string, mode os.FileMode) {
		t.Helper()
		if err := os.WriteFile(path, []byte(body), mode); err != nil {
			t.Fatal(err)
		}
	}
	write(filepath.Join(dir, "alpha.go"), "// +gobra\npackage tiny\ntype Alpha struct{}\nfunc (*Alpha) Start() {}\n", 0644)
	write(filepath.Join(dir, "explore.go"), "package tiny\nfunc Successors() {}\n", 0644)
	write(filepath.Join(bin, "docker"), `#!/bin/sh
[ "$1" = run ] || exit 0
cat <<'OUTPUT'
The verification of member .. - tiny.*Alpha.Start() did not terminate
The verification of 1 members timed out.
OUTPUT
exit 1
`, 0755)
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	// Produce the error through the real language adapter and Gobra parser.
	// The existing synthesis path wraps exactly this public error when its
	// final gate cannot run, and leaves Final nil rather than writing a receipt.
	code, err := (verify.Go{GobraImage: "gobra946"}).Verify(t.Context(), dir)
	if err == nil {
		t.Fatalf("Gobra timeout became a failed Code check: %+v", code)
	}
	runErr := fmt.Errorf("the final gate couldn't run: %w", verify.Public(err))
	text := buildFailedComment(nil, &synth.Result{}, runErr, Marker{Kind: KindFailed})
	for _, want := range []string{"I couldn't build the code", "final gate couldn't run", "alpha.go", "(*Alpha).Start", "A person needs to look at this."} {
		if !strings.Contains(text, want) {
			t.Errorf("factory post lost %q:\n%s", want, text)
		}
	}
	if !strings.Contains(strings.ToLower(text), "unfinished") && !strings.Contains(text, "did not terminate") {
		t.Errorf("post lost unfinished status:\n%s", text)
	}
	for _, bad := range []string{dir, "Successors", "active proof", "in progress", "draft pull request"} {
		if strings.Contains(text, bad) {
			t.Errorf("post invented or exposed %q:\n%s", bad, text)
		}
	}
}

package gobra_test

import (
	"context"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/gobra"
)

// Intended API: ParseRun(dir, combinedOutput, statsJSON, exitCode) (Result, error)
// is the same interpretation Run uses. Result.Members contains diagnostic
// Member values with ID, File, Symbol, Reported, Verified, Success and Duration.
// Symbols use Go receiver notation: (*Alpha).Start and (Beta).Start.
// Duration is time.Duration; it is meaningful only for Verified members.
// PackageTimeout defaults to 19m30s, independently of the 20m Timeout backstop.
// No field asserts that a member is currently active.
//
// The builder records these TWO REAL captures with the existing pinned image:
// testdata/progress946/{finished,timeout}/{tiny.go,output.txt,stats.json}.
// Each source is a selected package tiny with functions and methods; the
// finished capture includes (*Alpha).Start and (Beta).Start, and the timeout
// capture includes both verified and unverified members. output.txt retains
// combined stdout/stderr, unedited. README.md records the digest, exact commands,
// exit statuses, CPU quota and short timeout used. Do not manufacture stats by
// joining separate runs. The real integration regression must reproduce the
// timeout using these sources, and fail rather than skip missing prerequisites.
// The capture assertions below deliberately read the raw JSON independently:
// neither an AST inventory nor a preconstructed progress value can feed them.

type raw946 struct {
	verified, success bool
	duration          time.Duration
}

func write946(t *testing.T, path, body string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(body), 0644); err != nil {
		t.Fatal(err)
	}
}
func read946(t *testing.T, path string) []byte {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return b
}
func capture946(t *testing.T, kind string) (string, string, []byte, int) {
	t.Helper()
	root := filepath.Join("testdata", "progress946", kind)
	dir := t.TempDir()
	write946(t, filepath.Join(dir, "tiny.go"), string(read946(t, filepath.Join(root, "tiny.go"))))
	out := string(read946(t, filepath.Join(root, "output.txt")))
	stats := read946(t, filepath.Join(root, "stats.json"))
	code := 1
	if strings.Contains(out, "Gobra found 0 errors") {
		code = 0
	}
	return dir, out, stats, code
}

// Discover Go member objects by the image's id, not by a guessed top-level
// envelope or Viper-member collection key. The three leaf fields and their
// units are the pinned image's contract described in #946.
func rawMembers946(t *testing.T, stats []byte) map[string]raw946 {
	t.Helper()
	var root any
	if err := json.Unmarshal(stats, &root); err != nil {
		t.Fatal(err)
	}
	result := map[string]raw946{}
	var visit func(any)
	visit = func(v any) {
		switch x := v.(type) {
		case []any:
			for _, e := range x {
				visit(e)
			}
		case map[string]any:
			if id, ok := x["id"].(string); ok && strings.HasPrefix(id, ".. - tiny.") {
				n := 0
				r := raw946{verified: true, success: true}
				var leaves func(any)
				leaves = func(v any) {
					switch y := v.(type) {
					case []any:
						for _, e := range y {
							leaves(e)
						}
					case map[string]any:
						verified, vok := y["verified"].(bool)
						success, sok := y["success"].(bool)
						ms, tok := y["time"].(float64)
						if vok && sok && tok {
							if ms < 0 {
								t.Fatalf("negative captured time: %v", y)
							}
							n++
							r.verified = r.verified && verified
							r.success = r.success && success
							r.duration += time.Duration(ms * float64(time.Millisecond))
							if !verified && (ms != 0 || !success) {
								t.Fatalf("unfinished capture differs from pinned image: %v", y)
							}
							return
						}
						for _, e := range y {
							leaves(e)
						}
					}
				}
				leaves(x)
				if n > 0 {
					if _, duplicate := result[id]; duplicate {
						t.Fatalf("duplicate Go member %s", id)
					}
					result[id] = r
					return
				}
			}
			for _, e := range x {
				visit(e)
			}
		}
	}
	visit(root)
	if len(result) < 2 {
		t.Fatalf("capture has no usable Go member statistics: %s", stats)
	}
	return result
}
func symbols946(t *testing.T, dir string) map[string]string {
	t.Helper()
	f, err := parser.ParseFile(token.NewFileSet(), filepath.Join(dir, "tiny.go"), nil, 0)
	if err != nil {
		t.Fatal(err)
	}
	symbols := map[string]string{}
	for _, d := range f.Decls {
		fn, ok := d.(*ast.FuncDecl)
		if !ok {
			continue
		}
		key, symbol := fn.Name.Name, fn.Name.Name
		if fn.Recv != nil {
			r := fn.Recv.List[0].Type
			prefix := ""
			if star, ok := r.(*ast.StarExpr); ok {
				prefix = "*"
				r = star.X
			}
			name, ok := r.(*ast.Ident)
			if !ok {
				t.Fatalf("capture needs a simple named receiver: %T", r)
			}
			key = prefix + name.Name + "." + fn.Name.Name
			symbol = "(" + prefix + name.Name + ")." + fn.Name.Name
		}
		symbols[key] = symbol
	}
	return symbols
}
func checkCapture946(t *testing.T, dir string, stats []byte, got gobra.Result) (int, int) {
	t.Helper()
	raw := rawMembers946(t, stats)
	symbols := symbols946(t, dir)
	seen := map[string]bool{}
	complete, unfinished := 0, 0
	for _, member := range got.Members {
		expected, ok := raw[member.ID]
		if !ok {
			continue
		} // Inventory rows may additionally say not reported.
		if seen[member.ID] {
			t.Fatalf("duplicate diagnostic member %s", member.ID)
		}
		seen[member.ID] = true
		key, _, _ := strings.Cut(strings.TrimPrefix(member.ID, ".. - tiny."), "(")
		symbol, exists := symbols[key]
		if !exists {
			t.Fatalf("captured member %q has no Go declaration", member.ID)
		}
		if member.File != "tiny.go" || member.Symbol != symbol || !member.Reported || member.Verified != expected.verified {
			t.Fatalf("source/status differs from raw capture: %+v, expected %s %+v", member, symbol, expected)
		}
		if member.Verified {
			complete++
			if member.Duration != expected.duration || member.Success != expected.success {
				t.Fatalf("lost measured completion: %+v, raw %+v", member, expected)
			}
		} else {
			unfinished++
			if member.Duration != 0 {
				t.Fatalf("fabricated completed timing: %+v", member)
			}
		}
	}
	if len(seen) != len(raw) {
		t.Fatalf("only %d of %d raw members survived: %+v", len(seen), len(raw), got.Members)
	}
	return complete, unfinished
}

func TestGobra946CapturedReports(t *testing.T) {
	for _, kind := range []string{"finished", "timeout"} {
		t.Run(kind, func(t *testing.T) {
			dir, out, stats, code := capture946(t, kind)
			got, err := gobra.ParseRun(dir, out, stats, code)
			complete, unfinished := checkCapture946(t, dir, stats, got)
			if kind == "finished" {
				if err != nil || complete < 3 || unfinished != 0 {
					t.Fatalf("finished capture: %+v %v", got, err)
				}
				names := map[string]bool{}
				for _, m := range got.Members {
					names[m.Symbol] = true
				}
				if !names["(*Alpha).Start"] || !names["(Beta).Start"] {
					t.Fatal("finished capture must distinguish two receivers with the same method name")
				}
				if got.Passed != (code == 0) {
					t.Fatal("diagnostics changed the verification outcome")
				}
				// Alter an actual captured leaf, rather than hand-building progress.
				var data any
				_ = json.Unmarshal(stats, &data)
				changed := false
				var failOne func(any)
				failOne = func(v any) {
					switch x := v.(type) {
					case []any:
						for _, e := range x {
							failOne(e)
						}
					case map[string]any:
						if !changed && x["verified"] == true {
							if _, ok := x["success"].(bool); ok {
								x["success"] = false
								changed = true
							}
						}
						for _, e := range x {
							failOne(e)
						}
					}
				}
				failOne(data)
				if !changed {
					t.Fatal("no completed raw leaf")
				}
				failed, _ := json.Marshal(data)
				res, e := gobra.ParseRun(dir, "Gobra found 1 errors.\n", failed, 1)
				if e != nil || res.Passed {
					t.Fatalf("ordinary failed proof became a gate error or pass: %+v %v", res, e)
				}
				checkCapture946(t, dir, failed, res)
			} else {
				if err == nil || got.Passed || complete == 0 || unfinished == 0 || !strings.Contains(out, "did not terminate") {
					t.Fatalf("need a genuine mixed timeout capture: %+v %v", got, err)
				}
				for _, m := range got.Members {
					if !m.Reported {
						continue
					}
					if !strings.Contains(err.Error(), m.Symbol) || !strings.Contains(err.Error(), m.File) {
						t.Fatalf("timeout omitted member: %+v\n%v", m, err)
					}
					if m.Verified && !strings.Contains(err.Error(), m.Duration.String()) {
						t.Fatalf("timeout omitted measured duration: %+v\n%v", m, err)
					}
				}
			}
		})
	}
}

// Replay only process output and files; never return a Result from the fake.
func init() {
	if os.Getenv("GOBRA946_DOCKER_CHILD") != "1" {
		return
	}
	args := os.Args[1:]
	if len(args) == 0 {
		os.Exit(91)
	}
	if args[0] != "run" {
		os.Exit(0)
	}
	_ = os.WriteFile(os.Getenv("GOBRA946_ARGS"), []byte(strings.Join(args, "\n")), 0600)
	mounts := map[string]string{}
	report := ""
	for i, a := range args {
		if i+1 == len(args) {
			continue
		}
		if a == "-v" || a == "--volume" {
			p := strings.Split(args[i+1], ":")
			if len(p) >= 2 {
				mounts[p[1]] = p[0]
			}
		}
		if a == "-g" {
			report = args[i+1]
		}
	}
	if src := os.Getenv("GOBRA946_STATS"); src != "" && report != "" {
		for guest, host := range mounts {
			if report == guest || strings.HasPrefix(report, guest+"/") {
				dest := filepath.Join(host, strings.TrimPrefix(report, guest))
				if err := os.MkdirAll(dest, 0755); err != nil {
					fmt.Fprintln(os.Stderr, err)
					os.Exit(92)
				}
				b, err := os.ReadFile(src)
				if err != nil {
					os.Exit(93)
				}
				if err = os.WriteFile(filepath.Join(dest, "stats.json"), b, 0644); err != nil {
					os.Exit(94)
				}
			}
		}
	}
	fmt.Print(os.Getenv("GOBRA946_OUTPUT"))
	code, _ := strconv.Atoi(os.Getenv("GOBRA946_EXIT"))
	os.Exit(code)
}
func docker946(t *testing.T, out string, stats []byte, code int) string {
	t.Helper()
	bin := t.TempDir()
	log := filepath.Join(t.TempDir(), "args")
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	script := "#!/bin/sh\nexport GOBRA946_DOCKER_CHILD=1\nexec '" + strings.ReplaceAll(exe, "'", "'\"'\"'") + "' \"$@\"\n"
	write946(t, filepath.Join(bin, "docker"), script)
	if err := os.Chmod(filepath.Join(bin, "docker"), 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("GOBRA946_OUTPUT", out)
	t.Setenv("GOBRA946_EXIT", strconv.Itoa(code))
	t.Setenv("GOBRA946_ARGS", log)
	t.Setenv("GOBRA946_STATS", "")
	if stats != nil {
		p := filepath.Join(t.TempDir(), "stats.json")
		write946(t, p, string(stats))
		t.Setenv("GOBRA946_STATS", p)
	}
	return log
}
func TestGobra946RunCollectsStatistics(t *testing.T) {
	if gobra.Timeout != 20*time.Minute || gobra.PackageTimeout != 19*time.Minute+30*time.Second {
		t.Fatal("F1 A's two limits changed")
	}
	for _, kind := range []string{"finished", "timeout"} {
		t.Run(kind, func(t *testing.T) {
			dir, out, stats, code := capture946(t, kind)
			log := docker946(t, out, stats, code)
			got, err := gobra.Run(t.Context(), "gobra946", dir, true)
			if (err != nil) != (kind == "timeout") {
				t.Fatalf("wrong timeout classification: %v", err)
			}
			checkCapture946(t, dir, stats, got)
			args := strings.Split(string(read946(t, log)), "\n")
			value := func(flag string) string {
				for i, a := range args {
					if a == flag && i+1 < len(args) {
						return args[i+1]
					}
				}
				return ""
			}
			inner := value("--packageTimeout")
			duration, e := time.ParseDuration(inner)
			if e != nil {
				if seconds, err := strconv.Atoi(inner); err == nil {
					duration = time.Duration(seconds) * time.Second
				}
			}
			if duration != 19*time.Minute+30*time.Second {
				t.Fatalf("package timeout = %q", inner)
			}
			if value("--network") != "none" || value("--platform") != "linux/amd64" || !strings.Contains("\n"+strings.Join(args, "\n")+"\n", "\n--overflow\n") {
				t.Fatalf("lost sandbox/overflow: %v", args)
			}
			report := value("-g")
			host := ""
			workRO := false
			for i, a := range args {
				if (a == "-v" || a == "--volume") && i+1 < len(args) {
					p := strings.Split(args[i+1], ":")
					if len(p) < 2 {
						continue
					}
					if p[1] == "/work" {
						workRO = len(p) == 3 && p[2] == "ro"
						continue
					}
					if p[1] == report {
						if len(p) == 3 && p[2] == "ro" {
							t.Fatal("read-only statistics mount")
						}
						host = p[0]
					}
				}
			}
			if !workRO || host == "" || report == "/work" || strings.HasPrefix(report, "/work/") {
				t.Fatalf("no separate writable report directory: %v", args)
			}
			if _, err := os.Stat(host); !os.IsNotExist(err) {
				t.Fatalf("report directory not cleaned: %v", err)
			}
			if _, err := os.Stat(filepath.Join(dir, "stats.json")); !os.IsNotExist(err) {
				t.Fatal("statistics written into the source tree")
			}
		})
	}
}

const timeout946 = "00:00:04.000 [thread-1] ERROR viper.gobra.Gobra - The verification of member .. - tiny.*Alpha.Start() did not terminate\n00:00:04.001 [thread-1] ERROR viper.gobra.Gobra - The verification of 1 members timed out.\n"

func source946(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	write946(t, filepath.Join(dir, "alpha.go"), "// +gobra\npackage tiny\ntype Alpha struct{}\nfunc (*Alpha) Start() {}\nfunc Inc() {}\n")
	write946(t, filepath.Join(dir, "beta.go"), "// +gobra\npackage tiny\ntype Beta struct{}\nfunc (Beta) Start() {}\n")
	write946(t, filepath.Join(dir, "explore.go"), "package tiny\nfunc Init() {}\nfunc Successors() {}\n")
	write946(t, filepath.Join(dir, "alpha_test.go"), "package tiny\nfunc TestHelper() {}\n")
	return dir
}
func TestGobra946BothTimeoutShapes(t *testing.T) {
	for _, tc := range []struct {
		name, out string
		exit      int
	}{{"during verification", timeout946, 1}, {"during desugaring", "The verification of package .. - tiny timed out after 4 seconds.\n", 0}} {
		t.Run(tc.name, func(t *testing.T) {
			docker946(t, tc.out, nil, tc.exit)
			dir := source946(t)
			res, err := gobra.Run(t.Context(), "gobra946", dir, false)
			if err == nil || res.Passed {
				t.Fatalf("timeout became an ordinary Code result: %+v %v", res, err)
			}
			text := err.Error()
			if !strings.Contains(text, "alpha.go") || !strings.Contains(text, "(*Alpha).Start") {
				t.Fatalf("no source-qualified method: %v", err)
			}
			if tc.exit == 1 && !strings.Contains(strings.ToLower(text), "unfinished") && !strings.Contains(text, "did not terminate") {
				t.Fatalf("actual unfinished report was lost: %v", err)
			}
			if tc.exit == 0 && !strings.Contains(strings.ToLower(text), "not reported") {
				t.Fatalf("phase timeout invented progress: %v", err)
			}
			for _, unwanted := range []string{"Successors", "TestHelper", dir, "active proof", "in progress"} {
				if strings.Contains(text, unwanted) {
					t.Fatalf("unfounded/public diagnostic %q: %s", unwanted, text)
				}
			}
		})
	}
}
func TestGobra946BackstopNamesOnlySelectedSources(t *testing.T) {
	dir := source946(t)
	bin := t.TempDir()
	write946(t, filepath.Join(bin, "docker"), "#!/bin/sh\n[ \"$1\" = rm ] && exit 0\nexec sleep 60\n")
	if err := os.Chmod(filepath.Join(bin, "docker"), 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	old := gobra.Timeout
	gobra.Timeout = 100 * time.Millisecond
	t.Cleanup(func() { gobra.Timeout = old })
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
	defer cancel()
	res, err := gobra.Run(ctx, "gobra946", dir, false)
	if err == nil || res.Passed {
		t.Fatalf("backstop did not stop run: %+v %v", res, err)
	}
	for _, want := range []string{"didn't finish within 100ms", "alpha.go", "(*Alpha).Start", "beta.go", "(Beta).Start", "Inc", "not reported"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("missing %q: %v", want, err)
		}
	}
	if strings.Contains(err.Error(), "Successors") || strings.Contains(err.Error(), "TestHelper") {
		t.Fatalf("unselected source presented as pending: %v", err)
	}
	// Check a fabricated completed timing, not the ambiguous substring '0s'.
	for _, line := range strings.Split(err.Error(), "\n") {
		if regexp.MustCompile(`(?i)\b(completed|verified|finished)\b.*\b0(ms|s)\b`).MatchString(line) {
			t.Fatalf("fabricated completion: %s", line)
		}
	}
}

